// wwe2k14 patch (Session 18, DLAA phase 1): camera jitter. The scene draws of a frame (viewports at least
// gpu_dlaa_jitter_min_width guest pixels wide, before the frame's scene-size depth resolve) get a sub-pixel offset of
// the host viewport origin: Halton(2, 3) over gpu_dlaa_jitter_phases phases, in [-0.5, 0.5) host pixels, advanced at
// each guest swap. The HUD and post passes come after the depth resolve and stay put; shadow maps etc. are smaller.
REXCVAR_DEFINE_BOOL(gpu_dlaa_jitter, false, "GPU",
                    "DLAA: sub-pixel jitter of the scene draws (Halton 2,3; host pixels); default off");
REXCVAR_DEFINE_STRING(gpu_dlaa_jitter_test, "", "GPU",
                      "DLAA jitter test: a fixed X,Y offset in host pixels instead of the Halton sequence (needs "
                      "gpu_dlaa_jitter); empty = the sequence");
REXCVAR_DEFINE_INT32(gpu_dlaa_jitter_phases, 8, "GPU", "DLAA jitter: length of the Halton sequence (DLAA: 8)");
REXCVAR_DEFINE_BOOL(gpu_dlaa, false, "GPU",
                    "DLAA step 3 (needs vulkan_streamline_dir + DLSS): the scene colour the post passes sample (the "
                    "first scene-size colour resolve after the depth, or gpu_dlaa_color_base) goes through DLSS in "
                    "DLAA mode with the jitter, depth and camera motion vectors; default off");
REXCVAR_DEFINE_DOUBLE(gpu_dlaa_jitter_sign, 1.0, "GPU", "DLAA: multiplies the jitter given to DLSS (+1 / -1)");
REXCVAR_DEFINE_DOUBLE(gpu_dlaa_reset_degrees, 15.0, "GPU",
                      "DLAA: a camera turn bigger than this (degrees) between frames counts as a cut (DLSS reset)");
REXCVAR_DEFINE_DOUBLE(gpu_dlaa_reset_distance, 0.0, "GPU",
                      "DLAA / DLSS (Session 24): a camera move longer than this (view units) between frames counts as "
                      "a cut (DLSS reset); 0 = off (the app sets 200 with --wwe2k14_dlss)");
REXCVAR_DEFINE_INT32(gpu_dlss_reset_hold_frames, 1, "GPU",
                     "DLSS (Session 27): after a camera cut, reset the history for this many frames (1 = the cut frame "
                     "only); the picture cuts 2-3 frames after the camera does, so 4 covers it");
REXCVAR_DEFINE_DOUBLE(gpu_dlaa_jitter_max_camera_px, 0.0, "GPU",
                      "DLAA / DLSS (Session 24): no jitter on frames after the camera moved more than this many render "
                      "pixels in a frame (estimated over the screen at view depths 300 and 2000): fast camera shots "
                      "use the game's own previous-frame blend, which turns a changing jitter into moire; 0 = always "
                      "jitter");
REXCVAR_DEFINE_BOOL(gpu_dlaa_motion, false, "GPU",
                    "DLAA step 2: camera motion vectors from the scene depth resolve (default off)");
REXCVAR_DEFINE_INT32(gpu_dlaa_debug, 0, "GPU",
                     "DLAA debug view (runs the motion pass): 1 = motion vectors as colour in the scene (red = left/"
                     "right, green = up/down, grey = still), 2 = scene depth as grey; 0 = off");
REXCVAR_DEFINE_INT32(gpu_dlaa_debug_scale, 16, "GPU", "DLAA debug view 1: pixels of motion for full colour");
REXCVAR_DEFINE_INT32(gpu_dlaa_depth_order, 0, "GPU",
                     "DLAA: depth word layout in the cached texel: 0 = depth in the top 24 bits, 1 = byte-swapped, "
                     "2 = the low 24 bits");
