// wwe2k14 patch (Session 95, the diagnostic run): an armed frame's draw from the register file's constants (the typed draw has its own in owned_front_own.cpp).
template <class IndexInfo>
static void DiagNoteRegisterDraw(VulkanCommandProcessor& cp, native::Draw& draw, const RegisterFile& regs, const Shader* vertex_shader, uint32_t index_count,
                                 const IndexInfo* index_info) {
  diag::DrawInputs in;
  in.draw = &draw;
  in.vertex_shader = vertex_shader;
  in.floats = &regs.values[XE_GPU_REG_SHADER_CONSTANT_000_X];
  in.ps_floats = &regs.values[XE_GPU_REG_SHADER_CONSTANT_256_X];
  in.bool_loop = &regs.values[XE_GPU_REG_SHADER_CONSTANT_BOOL_000_031];
  in.fetch = &regs.values[XE_GPU_REG_SHADER_CONSTANT_FETCH_00_0];
  in.vs_const = regs.values[XE_GPU_REG_SQ_VS_CONST];
  in.index_count = index_count;
  if (index_info && index_info->guest_base) {
    in.indexed = true;
    in.guest_index_base = index_info->guest_base;
    in.index_32bit = index_info->format == xenos::IndexFormat::kInt32;
    in.index_endian = uint32_t(index_info->endianness);
  }
  diag::NoteDraw(cp, in);
}

