// wwe2k14 patch (Session 66, B2.1): VulkanPipelineCache::GetVertexFetchEndianKey's key as the vertex modification holds
// it (0 for a shader that is not specialised).
inline uint32_t VertexEndianKeyOf(const SpirvShaderTranslator::Modification& modification) {
  return modification.vertex.vertex_fetch_endian_spec ? (1u | (uint32_t(modification.vertex.vertex_fetch_endians) << 1))
                                                      : 0u;
}

