// wwe2k14 patch (Session 95, r6gamma, GAMMAID): the 256-entry table pass for the table the console starts with (every
// channel i * 0x3FF / 0xFF, command_processor.cpp Initialize), computed instead of fetched. Same bindings as the table pass
// (the ramp set stays bound and unread). `swap_rb`: the source texture holds red and blue the other way round.
std::string GetSwapApplyGammaIdentityComputeSource(bool swap_rb) {
  std::string source = R"(#version 450
layout(local_size_x = 16, local_size_y = 8, local_size_z = 1) in;

layout(push_constant) uniform XeApplyGammaRampConstants {
  uvec2 xe_apply_gamma_size;
};

layout(set = 0, binding = 0) uniform textureBuffer xe_apply_gamma_ramp;
layout(set = 1, binding = 0) uniform texture2D xe_apply_gamma_source;
layout(set = 2, binding = 0, rgb10_a2) writeonly uniform image2D xe_apply_gamma_dest;

void main() {
  ivec2 pixel = ivec2(gl_GlobalInvocationID.xy);
  if (any(greaterThanEqual(uvec2(pixel), xe_apply_gamma_size))) {
    return;
  }

  uvec3 source = uvec3(texelFetch(xe_apply_gamma_source, pixel, 0).rgb * 255.0 + vec3(0.5))SWIZZLE;
  uvec3 ramp = source * 1023u / 255u;
  imageStore(xe_apply_gamma_dest, pixel, vec4(vec3(ramp) * (1.0 / 1023.0), 1.0));
}
)";
  const size_t at = source.find("SWIZZLE");
  source.replace(at, 7, swap_rb ? ".bgr" : "");
  return source;
}

