// wwe2k14 patch (Session 80, frame structure census): with the segment log, the textures the next draw samples - each
// used fetch constant's guest page, format and size - so a reader can match every copy to the passes that read it.
void VulkanCommandProcessor::NativeLogDrawTextures(uint32_t used_texture_mask) {
  std::string line = "draw textures:";
  for (uint32_t i = 0; i < 32; ++i) {
    if (!(used_texture_mask & (uint32_t(1) << i))) continue;
    uint32_t page = 0, format = 0, width = 0, height = 0;
    if (!texture_cache_->GetActiveTextureInfo(i, page, format, width, height)) {
      line += fmt::format(" fc{} none", i);
      continue;
    }
    line += fmt::format(" fc{} 0x{:05X} f{} {}x{}", i, page, format, width, height);
  }
  native_->SegLogLine(line);
}

