// wwe2k14 patch (Session 92, M4f-C): under THE CUT the targets a typed draw serves its textures against are the typed state's (native/owned_front_own.cpp sets them
// the draw and leave them set); its only caller under the cut is RequestTextures, called from DrawFromBase. nullptr = the register source as before.
static const OwnedServeTargets* g_owned_serve_targets = nullptr;
void OwnedServeTargetsSet(const OwnedServeTargets* t) { g_owned_serve_targets = t; }
// wwe2k14 patch (Session 93, gpu_d3d_typed_repeat): a typed draw's repeat (RepeatDrawFast over the typed state): the vertex float constants it uploads and the
// typed key state (the fetch words) its endian / pixel spec checks read. nullptr = the register file as before (the old paths).
static const uint32_t* g_repeat_typed_vs_float = nullptr;
static const VulkanPipelineCache::TypedKeyState* g_repeat_typed_keys = nullptr;
void OwnedRepeatSourceSet(const uint32_t* vs_float, const void* keys) {
  g_repeat_typed_vs_float = vs_float;
  g_repeat_typed_keys = static_cast<const VulkanPipelineCache::TypedKeyState*>(keys);
}
// wwe2k14 patch (Session 94, gpu_d3d_decouple bit 3): see owned_record.h. Command thread only.
static const uint32_t* g_view1_vs_float = nullptr;
void OwnedViewFloatSet(const uint32_t* vs_float_view0) { g_view1_vs_float = vs_float_view0; }
VkImageView VulkanCommandProcessor::NativeServeView(void* texture, uint32_t width, uint32_t height, VkFormat format,
                                                    const VkComponentMapping& components) {
  if (!native_) return VK_NULL_HANDLE;
  if (g_owned_serve_targets) {  // (M4f-C, the cut: the typed RB words; no register source)
    native::NativeRenderer::ServeTargets typed;
    typed.surface_info = g_owned_serve_targets->surface_info;
    for (uint32_t i = 0; i < 4; ++i) typed.color_info[i] = g_owned_serve_targets->color_info[i];
    typed.color_mask = g_owned_serve_targets->color_mask;
    return native_->TruthServeView(texture, width, height, format, components, typed);
  }
  const RegisterFile& regs = DrawRegs();
  native::NativeRenderer::ServeTargets targets;
  targets.surface_info = regs[XE_GPU_REG_RB_SURFACE_INFO];
  targets.color_info[0] = regs[XE_GPU_REG_RB_COLOR_INFO];
  targets.color_info[1] = regs[XE_GPU_REG_RB_COLOR1_INFO];
  targets.color_info[2] = regs[XE_GPU_REG_RB_COLOR2_INFO];
  targets.color_info[3] = regs[XE_GPU_REG_RB_COLOR3_INFO];
  // (The targets the pixel shader writes, as the draw takes them: games leave several bound at one EDRAM base.)
  const Shader* pixel_shader = active_pixel_shader();
  targets.color_mask =
      draw_util::GetNormalizedColorMask(regs, pixel_shader ? pixel_shader->writes_color_targets() : 0);
  return native_->TruthServeView(texture, width, height, format, components, targets);
}

